    ("presentation-outline", "Build a presentation from an outline", [("structure", "document", "slide-plan.json", "Organize a narrative for the requested audience; mark unsupported claims"), ("design", "presentation", "presentation.pptx", "Build slides following audience/template/page-count constraints; inspect text fit and citations")]),
    ("presentation-chart-refresh", "Refresh presentation charts", [("reconcile", "spreadsheet", "chart-data.xlsx", "Reconcile new data with chart series and units in the supplied deck"), ("refresh", "presentation", "refreshed.pptx", "Update requested chart data and values in a copy while preserving unrelated slides"), ("check", "document", "refresh-audit.json", "List changed slide/chart IDs and verify agreement with spreadsheet values")]),
