def build():
    return [{"id": name, "title": title, "required_inputs": ["source_files", "instructions"],
             "steps": [{"id": key, "app": app,
                        "instruction": text + ". Use source_files and instructions from inputs; preserve sources, save under work_dir, read back outputs and report uncertainty.",
                        "depends_on": [stages[i-1][0]] if i else [], "retry_safe": True,
                        "max_attempts": 2, "checks": [{"path": path, "format": path.rsplit('.',1)[1]}]}
                       for i, (key, app, path, text) in enumerate(stages)]}
            for name, title, stages in EXAMPLES]


if __name__ == "__main__":
    output = Path(__file__).resolve().parents[2] / "agent/decurix_agent/workflow_examples.json"
    output.write_text(json.dumps(build(), indent=2) + "\n", encoding="utf-8")
    print(f"Wrote {len(EXAMPLES)} workflow examples")
